function computeProfileStatus(p) {
  const filled = PROFILE_REQUIRED_FIELDS.filter((f) => !!p[f]);
  if (filled.length === PROFILE_REQUIRED_FIELDS.length) return "complete";
  if (filled.length > 0) return "partial";
  return "incomplete";
}
