    bankAccountNumber: String(row.bank_account_number),
    bankName: row.bank_name == null ? null : String(row.bank_name),
    currency: String(row.currency_code),
    settlementDelayBusinessDays: number4(row.settlement_delay_business_days, "settlement_delay_business_days"),
    mdrRate: number4(row.mdr_rate, "mdr_rate"),
    fixedProviderFee: number4(row.fixed_provider_fee, "fixed_provider_fee"),
    feeTaxRate: number4(row.fee_tax_rate, "fee_tax_rate"),
